def catalogue():
    result = _catalogue()
    for name in CONTAINER_OPERATIONS:
        operation = result['operations'][name]
        operation['keywords'] = list(operation['keywords']) + [k for k in CONTAINER_KEYWORDS if k not in operation['keywords']]
        operation['semantics'] = list(operation['semantics']) + CONTAINER_SEMANTICS[name]
        if name in CONTAINER_EXAMPLES:
            operation['examples'] = list(operation['examples']) + [CONTAINER_EXAMPLES[name]]
        if name == 'removeMetadata':
            operation['examples'] = list(operation['examples']) + [CONTAINER_MINIMISE_EXAMPLE]
    return result
